command:
// Drops the selected or targeted token onto the surface below it and applies fall damage.
// A creature that can fly or hover stays aloft. A prone or speed 0 flyer still falls.
// Useful when a creature ends up airborne outside of normal forced movement.
const token = canvas.tokens.controlled[0] ?? [...game.user.targets][0] ?? null;
if (!token) { ui.notifications.warn('Select or target a token first.'); return; }
await game.modules.get('draw-steel-combat-tools').api.fall(token, null, { silent: false });
